import { gql } from "~/gql";

// Operation names are global across erxes; keep the plugin prefix. gql() is
// generated by codegen — write documents as static strings (no `${}`), and
// let Apollo hooks infer their types from the document.

export const STATUS_QUERY = gql(`
  query educationStatus {
    educationStatus {
      plugin
      version
      subdomain
      userId
      userEmail
      aiEnabled
      aiModel
      chimegeEnabled
    }
  }
`);

export const ME_QUERY = gql(`
  query educationMe {
    educationMe {
      userId
      name
      avatar
      xp
      points
      level
      levelXp
      levelSize
      streak
      bestStreak
      freezes
      owned
      lessonsCompleted
      accuracy
      cardsStudied
      teacherRewards
      practicedToday
      canTeach
      mistakes {
        word
        wrong
        sentence
        ruleTitle
        rule
        count
      }
      heatmap {
        day
        count
      }
    }
  }
`);

export const LESSONS_QUERY = gql(`
  query educationLessons {
    educationLessons {
      _id
      title
      description
      emoji
      color
      source
      itemCount
      bestScore
    }
  }
`);

export const LESSON_QUERY = gql(`
  query educationLesson($_id: String!) {
    educationLesson(_id: $_id) {
      _id
      title
      description
      emoji
      color
      items {
        mode
        sentence
        target
        wrongForms
        ruleTitle
        rule
      }
    }
  }
`);

export const CARDS_QUERY = gql(`
  query educationCards {
    educationCards {
      _id
      code
      cyrillic
      script
      galig
      meaning
      meaningMn
      rule
      example
      emoji
      premium
      locked
      grade
      reps
      dueAt
      due
    }
  }
`);

export const SHOP_QUERY = gql(`
  query educationShopItems {
    educationShopItems {
      code
      kind
      title
      description
      emoji
      cost
      repeatable
    }
  }
`);

export const CLASS_QUERY = gql(`
  query educationClassOverview {
    educationClassOverview {
      studentCount
      activeToday
      lessonsCompleted
      accuracy
      students {
        userId
        name
        email
        avatar
        xp
        level
        streak
        lessonsCompleted
        accuracy
        mistakeCount
        lastActiveDay
        activeToday
        teacherRewards
      }
      topMistakes {
        word
        ruleTitle
        rule
        total
        students
      }
    }
  }
`);

export const SUBMIT_ATTEMPT = gql(`
  mutation educationSubmitAttempt($lessonId: String!, $answers: [EducationAnswerInput!]!) {
    educationSubmitAttempt(lessonId: $lessonId, answers: $answers) {
      xpEarned
      correct
      total
      perfect
      streakExtended
      freezeUsed
      progress {
        userId
        xp
        points
        level
        streak
      }
    }
  }
`);

export const REVIEW_COMPLETE = gql(`
  mutation educationReviewComplete($words: [String!]!) {
    educationReviewComplete(words: $words) {
      userId
      xp
      points
    }
  }
`);

export const CARD_STUDIED = gql(`
  mutation educationCardStudied($code: String!) {
    educationCardStudied(code: $code) {
      userId
      xp
      points
      cardsStudied
    }
  }
`);

export const SHOP_BUY = gql(`
  mutation educationShopBuy($code: String!) {
    educationShopBuy(code: $code) {
      userId
      points
      avatar
      owned
      freezes
      teacherRewards
    }
  }
`);

export const SET_AVATAR = gql(`
  mutation educationSetAvatar($code: String!) {
    educationSetAvatar(code: $code) {
      userId
      avatar
    }
  }
`);

export const AI_CHECK = gql(`
  mutation educationAiCheck($text: String!) {
    educationAiCheck(text: $text) {
      source
      corrected
      tip
      xpEarned
      reportJson
      issues {
        wrong
        right
        rule
      }
      words {
        originalWord
        isCorrect
        correctedWord
        errorType
        explanationMn
        suggestions
      }
    }
  }
`);

export const LESSON_ADD = gql(`
  mutation educationLessonAdd($title: String!, $description: String, $emoji: String, $items: [EducationLessonItemInput!]!) {
    educationLessonAdd(title: $title, description: $description, emoji: $emoji, items: $items) {
      _id
      title
    }
  }
`);

export const LESSON_GENERATE = gql(`
  mutation educationLessonGenerate($topic: String!, $count: Int) {
    educationLessonGenerate(topic: $topic, count: $count) {
      _id
      title
      itemCount
    }
  }
`);

export const LESSON_REMOVE = gql(`
  mutation educationLessonRemove($_id: String!) {
    educationLessonRemove(_id: $_id)
  }
`);

export const TTS = gql(`
  mutation educationTts($text: String!) {
    educationTts(text: $text) {
      audioBase64
      mimeType
    }
  }
`);

export const CARD_REVIEW = gql(`
  mutation educationCardReview($code: String!, $typed: String, $selfGrade: Int) {
    educationCardReview(code: $code, typed: $typed, selfGrade: $selfGrade) {
      grade
      nextLabel
      dueAt
      xpEarned
      spelling {
        originalWord
        isCorrect
        correctedWord
        errorType
        explanationMn
      }
    }
  }
`);
